import {termTeaching} from './concept-guide-ui.js';
import {foundations} from './data/foundations.js';
import {backgrounds,learningTracks,availabilityLabels,trackName} from './data/learning-paths.js';
import {foundationStatus,learningRecommendation} from './learning-state.js';
import {escapeHTML as e} from './state.js';
const heading=(title,body)=>`<div class="page-heading"><div><span class="eyebrow">MODEL CRAFT · LEARN BY BUILDING</span><h1>${e(title)}</h1><p>${e(body)}</p></div></div>`;
const trackLink=id=>`<a href="${id==='common'?'#/foundations':`#/paths/${id}`}">${e(trackName(id))}</a>`;
export function learnerControls(state){const p=state.learner;return `<section class="panel panel-pad"><h2>选择起点和兴趣，也可以直接开始</h2><p>这些选项只调整提示，不跳过验收、不锁定课程。无需填写姓名、职业、公司或设备。</p><div class="learning-preferences"><label>当前起点<select class="field" data-learner="background">${backgrounds.map(b=>`<option value="${b.id}" ${b.id===p.background?'selected':''}>${e(b.label)}</option>`).join('')}</select></label><label>感兴趣的方向<select class="field" data-learner="track"><option value="all" ${p.track==='all'?'selected':''}>先看全景，暂不选择</option>${learningTracks.map(t=>`<option value="${t.id}" ${t.id===p.track?'selected':''}>${e(t.name)}</option>`).join('')}</select></label><label>每周预计投入<select class="field" data-learner="weeklyHours">${[3,6,10].map(n=>`<option value="${n}" ${p.weeklyHours===n?'selected':''}>约 ${n} 小时</option>`).join('')}</select></label></div><div id="learning-recommendation" aria-live="polite">${recommendation(state)}</div></section>`;}
function recommendation(state){const p=state.learner,t=learningTracks.find(x=>x.id===p.track),intro={explore:'不确定也没关系，从一个生活中的预测例子开始，不先考陌生术语。',new:'从变量、函数、循环和四则运算开始。每个新符号先解释再使用；需要时可以重复单个例子。',code:'先核对模型、损失、更新与验证的区别。熟悉的 Python 语法可以跳读，但仍用代码与实验检验理解。',train:'可直接查看专题的前置能力与验收，或用公共练习查缺补漏；选择经验等级不会自动生成通过记录。'}[p.background];return `<p>${intro}</p><p>${t?`当前兴趣：<b>${e(t.name)}</b>。该专题预算约 ${t.hours[0]}–${t.hours[1]} 小时，按每周 ${p.weeklyHours} 小时约 ${Math.ceil(t.hours[0]/p.weeklyHours)}–${Math.ceil(t.hours[1]/p.weeklyHours)} 周；不含前置补课与等待算力，部分实战仍待补齐。`:`先完成公共入门，再决定方向。入门含练习约 6–12 小时，按每周 ${p.weeklyHours} 小时约 ${Math.ceil(6/p.weeklyHours)}–${Math.ceil(12/p.weeklyHours)} 周；完全没有编程经验可增加练习时间。`}</p><p class="small muted">节奏是估算，掌握情况由理解检查、当前代码和实验观察共同判断。基础练习可以在浏览器完成，不要求 GPU。</p>`;}
function foundationCards(state,exercises){return foundations.map((l,i)=>{const s=foundationStatus(l,state,exercises);return `<a class="panel panel-pad learning-foundation-card" href="#/foundations/${l.id}"><span class="badge">公共入门 ${i+1} · ${s.complete?'当前验收通过':'可开始学习'}</span><h3>${e(l.title)}</h3><p>${e(l.question)}</p><p class="small muted">${e(l.goal)} · 约 ${l.hours[0]}–${l.hours[1]} 小时</p></a>`;}).join('');}
function map(){return `<section class="panel panel-pad"><h2>共同的训练方法，连接不同的任务</h2><a class="learning-map-root" href="#/foundations"><b>公共基础：输入 → 预测 → 误差 → 更新 → 独立验证</b><span>继续补齐张量、自动求导和小神经网络，再按前置能力选分支。</span></a><div class="learning-map-lanes">${[['language','posttraining','agents'],['vision','image','video'],['world','robotics']].map(ids=>`<div class="learning-map-lane">${ids.map(id=>`<a href="#/paths/${id}"><b>${e(trackName(id))}</b><span>${e(learningTracks.find(t=>t.id===id).question)}</span></a>`).join('<span class="learning-map-arrow" aria-hidden="true">↓</span>')}</div>`).join('')}</div><a class="learning-map-base" href="#/paths/systems"><b>各方向共同需要：数据、评测、训练推理工程与迭代证据 →</b></a><p class="small muted">连线表示常见学习衔接，不代表每条路线都必须走完。低维世界模型可直接从公共基础开始；选择机器人规划路线时才需要先学世界模型。</p></section>`;}
export function pathsPage(id,state){const t=learningTracks.find(t=>t.id===id);if(!id)return `<div class="learning-page">${heading('公共基础之后，选择你想解决的问题。','这些是学习方向，不是互斥的模型类型。后训练与工程可以用于不同模态；世界模型可以使用视频、状态或其他表示。')}${map()}<div class="learning-card-grid">${learningTracks.map(t=>`<article class="panel panel-pad"><h2><a href="#/paths/${t.id}">${e(t.name)} →</a></h2><p>${e(t.question)}</p><p><b>前置：</b>${t.prerequisites.map(trackLink).join('、')}</p><p>${e(t.outcome)}</p><div class="row wrap">${Object.entries(availabilityLabels).map(([key,label])=>{const n=t.steps.filter(s=>s.availability===key).length;return n?`<span class="badge ${key==='planned'?'badge-orange':'badge-gray'}">${label} ${n}</span>`:'';}).join('')}</div></article>`).join('')}</div><p class="small muted">专题预算不含全部前置和外部训练等待，不要求把所有专题工时相加后在三个月内学完。设备要求在实际运行项中说明。</p></div>`;
 if(!t)return heading('没有找到这个方向','从方向总览重新选择。')+'<a href="#/paths">返回学习方向</a>';
 return `<div class="learning-page">${heading(t.name,t.question)}<a href="#/paths">← 所有方向</a><section class="panel panel-pad"><p>${e(t.intro)}</p><p><b>先具备：</b>${t.prerequisites.map(trackLink).join('、')}</p>${t.optional.length?`<p><b>按任务再补：</b>${t.optional.map(trackLink).join('、')}</p>`:''}<p><b>本专题目标：</b>${e(t.outcome)}</p><p class="small muted">约 ${t.hours[0]}–${t.hours[1]} 小时；是含待补实战的专题规划预算，不代表所有内容现在已可完成。按每周 ${state.learner.weeklyHours} 小时可分多次推进。</p><button class="btn" data-choose-track="${t.id}">${state.learner.track===t.id?'已设为当前兴趣':'设为当前兴趣方向'}</button><p id="learning-track-status" class="small muted" role="status">选择只影响导航提示，不改变已完成记录。</p></section><section class="panel panel-pad"><h2>你将在具体问题里遇到这些概念</h2><ul>${t.topics.map(x=>`<li>${e(x)}</li>`).join('')}</ul><p>不用先记住所有缩写；每个入口的讲解负责先定义再使用。</p></section><ol class="learning-track-steps">${t.steps.map((s,i)=>`<li class="panel panel-pad"><div class="row wrap"><span class="badge badge-gray">步骤 ${i+1}</span><span class="badge ${s.availability==='planned'?'badge-orange':''}">${availabilityLabels[s.availability]}</span></div><h2>${e(s.title)}</h2><p><b>为什么到这一步：</b>${e(s.why)}</p><p><b>需要交付：</b>${e(s.deliverable)}</p>${s.href?`<a class="btn btn-primary" href="${s.href}">打开对应讲解与练习 →</a>`:'<p class="learning-pending">此项尚无完整带练入口，不能据此标记完成。可以先学习前面的已有内容。</p>'}</li>`).join('')}</ol><section class="panel panel-pad"><h2>所有方向共享同一套工程职责</h2><div class="learning-module-row">${['data：样本与划分','models：编码器、骨干、输出','training：目标与参数更新','inference：生成与执行','evaluation：指标与失败','experiments：配置和对照'].map(x=>`<code>${e(x)}</code>`).join('')}</div><p>这是通用职责蓝图，各项目的真实目录可以不同。替换组件时先检查输入输出、状态与训练目标，再验收效果。</p><div class="row wrap"><a class="btn" href="#/blueprint">看机器人案例如何落到真实文件</a><a class="btn" href="#/notebook">记录本次实验</a></div></section></div>`;}
export function foundationPage(id,state,exercises,editor){if(!id)return `<div class="learning-page">${heading('公共基础：先把一个训练闭环讲明白。','所有方向都从输入、预测、更新与验证出发。没有编程经验先读第 1 节；有经验可直接检查并查缺补漏。')}<div class="learning-card-grid">${foundationCards(state,exercises)}</div><section class="panel panel-pad"><h2>公共进阶：把小函数换成神经网络</h2><p>入门之后还需要理解成批数据的形状、自动求导和非线性表达。这些是语言、图像等分支共同使用的能力。</p><div class="row wrap"><a class="btn" href="#/lesson/w3-l2">张量与自动求导</a><a class="btn" href="#/lesson/w4-l1">小样本过拟合与模型诊断</a><a class="btn" href="#/day/w1-d7">综合编程验收</a><a class="btn" href="#/paths">选择后续方向</a></div><p>课程里的价格、文本或机器人都是例子；关注共同的输入、输出、训练和验证职责。</p></section></div>`;
 const lesson=foundations.find(l=>l.id===id);if(!lesson)return heading('没有找到这一节','从公共基础重新选择。')+'<a href="#/foundations">返回公共基础</a>';
 const index=foundations.indexOf(lesson),r=state.foundations[id]||{},ex=exercises.find(ex=>ex.id===lesson.exerciseId),next=foundations[index+1];
 return `<div class="learning-page">${heading(lesson.title,lesson.question)}<div class="row wrap"><a href="#/foundations">← 公共基础</a>${index?`<a href="#/foundations/${foundations[index-1].id}">回看上一节</a>`:''}</div><section class="panel panel-pad"><h2>开始前与完成后</h2><p><b>开始前：</b>${e(lesson.before)}</p><p><b>本节目标：</b>${e(lesson.goal)}</p><p>约 ${lesson.hours[0]}–${lesson.hours[1]} 小时，包含动手，可分多天完成。正文无需安装环境；网页代码首次运行需联网加载 Python。</p></section><article class="panel panel-pad learning-reading"><h2>先认识本节会用到的词</h2><dl class="learning-terms">${lesson.terms.map(([name,meaning])=>termTeaching({name,meaning})).join('')}</dl>${lesson.sections.map((s,i)=>`<section><h2>${i+1}. ${e(s.title)}</h2>${s.paragraphs.map(p=>`<p>${e(p)}</p>`).join('')}</section>`).join('')}<h2>把计算过程完整走一遍</h2><ol>${lesson.worked.map(x=>`<li>${e(x)}</li>`).join('')}</ol><h3>对照代码与输出</h3><pre><code>${e(lesson.example.code)}</code></pre><p>这段代码的输出：</p><pre><code>${e(lesson.example.output)}</code></pre><p>先逐行预测变量，再阅读下方题目。在编辑器中实现要求的函数；上面的独立示例不等于题目接口。</p></article><section class="panel panel-pad"><h2>动手：先样例，再完整检查</h2><ol>${lesson.practice.map(x=>`<li>${e(x)}</li>`).join('')}</ol><details><summary>遇到错误时，从哪里查？</summary><p>${e(lesson.recovery)}</p></details>${editor(ex)}</section><section class="panel panel-pad"><h2>只检查已经讲过的内容</h2>${lesson.checks.map((q,i)=>`<fieldset class="learning-question" data-foundation-question="${i}"><legend>${e(q.prompt)}</legend>${q.options.map((v,j)=>`<label><input type="radio" name="foundation-check-${i}" value="${j}" ${r.answers?.[i]===j?'checked':''}> ${e(v)}</label>`).join('')}<div class="learning-answer" role="status">${Number.isInteger(r.answers?.[i])?feedback(q,r.answers[i]):'先作答，再看解析。'}</div></fieldset>`).join('')}</section><section class="panel panel-pad"><h2>记录你实际观察到了什么</h2><label for="foundation-note">用自己的例子说明输入、改动和结果，至少 20 字。</label><textarea id="foundation-note" class="field" rows="5" placeholder="我先预测……；运行后……；修改……后……">${e(r.note||'')}</textarea><p id="foundation-note-status" class="small muted" role="status">保存在本机，可在设置中导出。</p><div id="foundation-completion">${foundationCompletion(lesson,state,exercises)}</div></section><section class="panel panel-pad"><h2>为什么继续下一步？</h2><p>${e(lesson.next)}</p><div class="row wrap"><a class="btn btn-primary" href="${next?`#/foundations/${next.id}`:'#/foundations'}">${next?'进入下一节':'回到公共进阶与综合验收'} →</a>${lesson.links.map(l=>`<a class="btn" href="${l.href}">${e(l.label)}</a>`).join('')}</div></section><p class="small muted">查证来源：<a href="https://docs.python.org/3/tutorial/controlflow.html#defining-functions" target="_blank" rel="noopener noreferrer">Python 函数与控制流</a> · <a href="https://docs.pytorch.org/tutorials/beginner/basics/autogradqs_tutorial.html" target="_blank" rel="noopener noreferrer">PyTorch 自动求导</a>。先完成本页，再按需深入。</p></div>`;}
function feedback(q,value){return `<b>${q.answer===value?'✓ 理解正确':'再检查这个原因'}</b><p>${e(q.explanation)}</p>`;}
export function foundationCompletion(lesson,state,exercises){const s=foundationStatus(lesson,state,exercises);return `<p><b>${s.complete?'✓ 当前入门验收通过':s.ready?'可以保存本节验收':'还需要：'+s.missing.join('、')}</b></p><p class="small muted">理解 ${s.correct}/${lesson.checks.length} · ${s.code?'当前代码已验证':'代码待验证'}${state.solutionsViewed.includes(lesson.exerciseId)?' · 看过参考解法':''}。修改代码会使旧成绩失效；个人观察不是完整模型效果认证。</p><button class="btn btn-primary" id="foundation-complete" ${s.ready?'':'disabled'}>保存本节验收</button>`;}
export function bindLearning(page,id,state,exercises,save){const controller=new window.AbortController(),q=s=>document.querySelector(s),on=(el,event,fn)=>el?.addEventListener(event,fn,{signal:controller.signal}),lesson=page==='foundations'?foundations.find(l=>l.id===id):null;
 const record=()=>state.foundations[lesson.id]??={answers:{},note:'',completedAt:''};
 const refresh=()=>{const panel=q('#foundation-completion');if(panel&&lesson)panel.innerHTML=foundationCompletion(lesson,state,exercises);};
 document.querySelectorAll('[data-learner]').forEach(input=>on(input,'change',()=>{const key=input.dataset.learner;state.learner[key]=key==='weeklyHours'?Number(input.value):input.value;save();q('#learning-recommendation').innerHTML=recommendation(state);}));
 document.querySelectorAll('[data-choose-track]').forEach(button=>on(button,'click',()=>{state.learner.track=button.dataset.chooseTrack;save();button.textContent='已设为当前兴趣';q('#learning-track-status').textContent='已保存。返回首页即可看到该方向提示；原学习记录保留。';}));
 if(lesson){document.querySelectorAll('[data-foundation-question]').forEach(group=>on(group,'change',event=>{const i=Number(group.dataset.foundationQuestion),value=Number(event.target.value);if(!Number.isInteger(value)||!lesson.checks[i].options[value])return;record().answers[i]=value;save();group.querySelector('.learning-answer').innerHTML=feedback(lesson.checks[i],value);refresh();}));on(q('#foundation-note'),'input',event=>{record().note=event.target.value;save();q('#foundation-note-status').textContent='观察已保存到本机。';refresh();});on(q('#foundation-completion'),'click',event=>{if(event.target.closest('#foundation-complete')&&foundationStatus(lesson,state,exercises).ready){record().completedAt=new Date().toISOString();save();refresh();}});}
 return ()=>controller.abort();
}
